// Block (composition) — a grouped agenda with loading and empty states.
// Stack owns arrangement; Badge/Separator own Component look, and SkeletonList owns loading content.
import type { Ref } from "react";
import { Badge } from "../components/Badge";
import { Separator } from "../components/Separator";
import { Stack } from "../layouts/Stack";
import { SkeletonList } from "./SkeletonList";
import "./AgendaList.css";

export interface AgendaListProps {
  groups: {
    label: string;
    items: { time: string; title: string; description?: string }[];
  }[];
  /** Renders skeleton placeholders while the agenda is loading. */
  isLoading?: boolean;
  /** Message shown when there is nothing scheduled. */
  emptyLabel?: string;
  className?: string;
  ref?: Ref<HTMLElement>;
}

export function AgendaList({
  groups,
  isLoading,
  emptyLabel = "Nothing scheduled",
  className,
  ref,
}: AgendaListProps) {
  if (isLoading) {
    return <SkeletonList rows={4} className={className} />;
  }
  if (groups.length === 0) {
    return (
      <p role="status" className={`sd-agendalist__empty sd-type-caption-medium${className ? ` ${className}` : ""}`}>
        {emptyLabel}
      </p>
    );
  }
  return (
    <Stack
      as="section"
      ref={ref}
      gap="large"
      aria-label="Agenda"
      className={className ? `sd-agendalist ${className}` : "sd-agendalist"}
    >
      {groups.map((group) => (
        <Stack key={group.label} gap="small" className="sd-agendalist__group">
          {/* CONTRASTIVE: one rung below the agenda rows it heads, as a collection's section-header. */}
          <>
            <h2 className="sd-agendalist__label sd-type-label-small">{group.label}</h2>
          </>
          <Separator />
          <Stack as="ol" gap="small" className="sd-agendalist__items">
            {group.items.map((item, index) => (
              <Stack
                as="li"
                key={`${item.time}-${item.title}-${index}`}
                direction={{ small: "column", medium: "row" }}
                gap={{ small: "2x-small", medium: "small" }}
                align={{ medium: "start" }}
                className="sd-agendalist__item"
              >
                <Badge className="sd-agendalist__time">{item.time}</Badge>
                <div className="sd-agendalist__content-inset">
                  <Stack gap="2x-small" className="sd-agendalist__content">
                    <span className="sd-type-body-medium-emphasized">{item.title}</span>
                    {item.description && (
                      <span className="sd-type-caption-medium">{item.description}</span>
                    )}
                  </Stack>
                </div>
              </Stack>
            ))}
          </Stack>
        </Stack>
      ))}
    </Stack>
  );
}

.sd-agendalist {
  width: 100%;
}

.sd-agendalist__label {
  margin: 0;
}

.sd-agendalist__items {
  margin: 0;
  padding: 0;
  list-style: none;
}

/* A Badge is a chip: content-sized on both axes. `flex: none` holds the MAIN axis, and at the
   small rung this row is a COLUMN, where a Stack's default `stretch` pulled the chip to the full
   358px. `align-self` is the cross-axis half of the same statement. */
.sd-agendalist__time {
  flex: none;
  align-self: start;
}

/* The content's Indent is the row's flex item now, so it carries the grow and the shrink. At the
   small rung the content stacks under the chip and takes the text line (component-contract.md §6
   rule 8); from `medium` up it starts after the chip and keeps the same inset. */
.sd-agendalist__content-inset {
  flex: 1;
  min-width: 0;
}

/* empty state — layout only (muted color inherits default; blocks own no color) */
.sd-agendalist__empty {
  padding: var(--sd-space-large);
  text-align: center;
}
